<?php
$pageTitle='Training tracker';$activePage='training_tracker.php';require __DIR__.'/../includes/agent_layout.php';
$rows=$pdo->query("SELECT u.first_name,u.last_name,u.email,COALESCE(t.modules_completed,0) completed,COALESCE(t.modules_total,12) total,COALESCE(t.hours_logged,0) hours_logged,COALESCE(t.status,'in_training') status FROM users u LEFT JOIN training_records t ON t.user_id=u.id WHERE u.pathway='internship' ORDER BY u.last_name")->fetchAll();
$completed=array_sum(array_column($rows,'completed'));$total=array_sum(array_column($rows,'total'));
?>
<div class="admin-heading"><div><h1>Training tracker</h1><p>Monitor module completion, training hours, and upcoming learning milestones.</p></div><div class="admin-actions"><a class="admin-btn" href="#">Export tracker</a><a class="admin-btn primary" href="#">+ Assign training</a></div></div><div class="metric-grid"><div class="metric-card"><small>Average completion</small><strong><?= $total ? round($completed/$total*100) : 0 ?>%</strong><span>Across all interns</span></div><div class="metric-card"><small>Modules completed</small><strong><?= $completed ?> / <?= $total ?></strong><span>Tracked in database</span></div><div class="metric-card"><small>Training hours logged</small><strong><?= number_format(array_sum(array_column($rows,'hours_logged'))) ?></strong><span>Current cohort</span></div><div class="metric-card"><small>Needs attention</small><strong><?= count(array_filter($rows,fn($r)=>$r['status']==='on_hold')) ?></strong><span>Follow-up required</span></div></div><section class="admin-panel data-panel"><div class="table-toolbar"><input placeholder="Search intern or module"><select><option>All tracks</option></select><select><option>All statuses</option></select></div><table class="admin-table"><thead><tr><th>Intern</th><th>Track</th><th>Completion</th><th>Hours logged</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= htmlspecialchars($row['first_name'].' '.$row['last_name']) ?></td><td>Customer Success</td><td><span class="progress"><i style="width:<?= (int)($row['completed']/$row['total']*100) ?>%"></i></span> <?= (int)($row['completed']/$row['total']*100) ?>%</td><td><?= htmlspecialchars($row['hours_logged']) ?> / 400 hrs</td><td><span class="badge info"><?= htmlspecialchars(str_replace('_',' ',$row['status'])) ?></span></td><td><a class="admin-btn" href="#">View tracker</a></td></tr><?php endforeach; ?></tbody></table></section><?php require __DIR__.'/../includes/admin_footer.php'; ?>